import{_ as a,o as t,c as i,a6 as n}from"./chunks/framework.BrkgobfX.js";const c=JSON.parse('{"title":"13 · 自动压缩：上下文快满了，把历史折叠成摘要","description":"缓存省钱但不缩小历史；当历史真的装不下，就得把老对话摘要掉。讲清压缩边界(保留近期、摘要远古)、摘要 prompt 为何是成败关键、proactive 与 reactive 两种触发，以及压缩与缓存那对绕不开的矛盾。","frontmatter":{"title":"13 · 自动压缩：上下文快满了，把历史折叠成摘要","description":"缓存省钱但不缩小历史；当历史真的装不下，就得把老对话摘要掉。讲清压缩边界(保留近期、摘要远古)、摘要 prompt 为何是成败关键、proactive 与 reactive 两种触发，以及压缩与缓存那对绕不开的矛盾。","source":"https://daiw.org/manual/llm-to-agent/auto-compaction"},"headers":[],"relativePath":"manual/agent/llm-to-agent/auto-compaction.md","filePath":"manual/agent/llm-to-agent/auto-compaction.md"}'),e={name:"manual/agent/llm-to-agent/auto-compaction.md"};function l(r,s,p,o,h,g){return t(),i("div",null,[...s[0]||(s[0]=[n(`<h1 id="_13-·-自动压缩-上下文快满了-把历史折叠成摘要" tabindex="-1">13 · 自动压缩：上下文快满了，把历史折叠成摘要 <a class="header-anchor" href="#_13-·-自动压缩-上下文快满了-把历史折叠成摘要" aria-label="Permalink to &quot;13 · 自动压缩：上下文快满了，把历史折叠成摘要&quot;">​</a></h1><blockquote><p>缓存省钱但不缩小历史；当历史真的装不下，就得把老对话摘要掉。讲清压缩边界(保留近期、摘要远古)、摘要 prompt 为何是成败关键、proactive 与 reactive 两种触发，以及压缩与缓存那对绕不开的矛盾。</p></blockquote><p><a href="/Front2Full/manual/agent/llm-to-agent/prompt-caching">缓存</a>解决了“重复的别重算”，但它救不了另一半问题：当历史本身<strong>膨胀到装不下</strong>窗口时，缓存无能为力——你得真的<strong>把历史变小</strong>。这一篇，我们正面处理这头猛兽。</p><h2 id="一、背景-缓存不缩小任何东西" tabindex="-1">一、背景：缓存不缩小任何东西 <a class="header-anchor" href="#一、背景-缓存不缩小任何东西" aria-label="Permalink to &quot;一、背景：缓存不缩小任何东西&quot;">​</a></h2><p>分清两件事：</p><ul><li><a href="/Front2Full/manual/agent/llm-to-agent/prompt-caching">缓存</a>让你<strong>便宜地重发</strong>同一段历史，但历史该多大还多大——它一个 token 都没减少。</li><li>当<a href="/Front2Full/manual/agent/llm-to-agent/token-budget">水位线</a>告诉你“上下文到 85% 了”，再便宜的重发也没用，<strong>窗口就要装不下了</strong>。</li></ul><p>这时唯一的出路是：<strong>把一部分历史，从“逐字保留”变成“摘要保留”</strong>——用一小段摘要，替换掉一大坨老消息。这就是压缩(compaction)。</p><h2 id="二、解决方案-保留近期-摘要远古" tabindex="-1">二、解决方案：保留近期，摘要远古 <a class="header-anchor" href="#二、解决方案-保留近期-摘要远古" aria-label="Permalink to &quot;二、解决方案：保留近期，摘要远古&quot;">​</a></h2><p>粗暴地把整个历史塞给模型“缩短一下”是不行的——你会丢掉太多细节。聪明的压缩有个清晰的结构：<strong>一条压缩边界，把历史切成两半。</strong></p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>压缩前:[msg1][msg2][msg3]...[msg40][msg41][msg42]   ← 太长,装不下</span></span>
<span class="line"><span>                    压缩边界 ┘</span></span>
<span class="line"><span>压缩后:[—— 摘要:msg1..msg40 的精华 ——][msg41][msg42]  ← 瘦身完成</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li><strong>边界之前</strong>(远古历史)：喂给模型，让它写一段<strong>结构化摘要</strong>，然后用这段摘要<strong>替换</strong>掉这几十条消息。</li><li><strong>边界之后</strong>(近期历史)：<strong>逐字保留</strong>——模型干活最依赖最近的细节(刚读的文件、刚跑的报错)，这部分不能动。</li></ul><p>压缩本身是<strong>一次额外的 LLM 调用</strong>：把要压缩的历史发给模型，配一个专门的“压缩 prompt”，拿回摘要：</p><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> compact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">oldMessages</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[])</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Promise</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> res</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.messages.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    model, max_tokens: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2048</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    system: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">COMPACT_PROMPT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ← 摘要的质量,全系于这个 prompt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    messages: [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">oldMessages, { role: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;user&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, content: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;请把以上对话压缩成结构化摘要。&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  })</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  return</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> textOf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(res)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 压缩后的新历史 = [摘要] + 近期逐字保留的尾部</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> newMessages</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [{ role: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;user&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, content: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`&lt;summary&gt;\${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">summary</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&lt;/summary&gt;\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">recentTail]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h2 id="三、决定性细节-摘要-prompt-就是成败本身" tabindex="-1">三、决定性细节：摘要 prompt 就是成败本身 <a class="header-anchor" href="#三、决定性细节-摘要-prompt-就是成败本身" aria-label="Permalink to &quot;三、决定性细节：摘要 prompt 就是成败本身&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>压缩的全部风险，集中在那个摘要 prompt 上。</strong> 摘要写好了，Agent 压缩完能无缝接着干，仿佛什么都没发生；摘要写砸了，Agent <strong>当场失忆</strong>——忘了自己在修哪个 bug、忘了已经改过哪些文件、忘了用户最初的要求，然后开始胡乱重复劳动或跑偏。这是压缩最危险的地方：<strong>它是一个有损操作，而损掉的可能正是关键信息。</strong></p></div><p>所以摘要 prompt 必须明确要求模型<strong>保留那些“继续干活所必需”的东西</strong>，通常包括：</p><ul><li><strong>当前任务是什么</strong>、用户最初的完整意图。</li><li><strong>已经做了什么</strong>：改过哪些文件、跑过哪些命令、得到什么结果。</li><li><strong>关键事实与决策</strong>：发现的根因、选定的方案、踩过的坑。</li><li><strong>当前进行到哪一步</strong>、下一步打算干什么。</li><li><strong>重要的文件路径、符号名、配置值</strong>——这些具体的“锚点”丢了就得重新去查。</li></ul><p>一个好的摘要 prompt，往往会给出一个<strong>固定的结构模板</strong>(任务/已完成/关键发现/当前状态/下一步)，强制模型逐项填写，而不是随意“写个大概”。<strong>把摘要的结构定死，是对抗“压缩即失忆”的主要武器。</strong></p><h2 id="四、两种触发-proactive-vs-reactive" tabindex="-1">四、两种触发：proactive vs reactive <a class="header-anchor" href="#四、两种触发-proactive-vs-reactive" aria-label="Permalink to &quot;四、两种触发：proactive vs reactive&quot;">​</a></h2><p>什么时候压缩？有两条路，成熟系统两条都要：</p><table tabindex="0"><thead><tr><th></th><th>Proactive(主动)</th><th>Reactive(被动)</th></tr></thead><tbody><tr><td>触发</td><td>水位到阈值(如 85%)，<strong>主动</strong>压</td><td>请求已经 <code>413</code> 超长了，<strong>被迫</strong>压</td></tr><tr><td>时机</td><td>撞墙<strong>之前</strong></td><td>撞墙<strong>之后</strong>恢复</td></tr><tr><td>心态</td><td>未雨绸缪</td><td>亡羊补牢</td></tr></tbody></table><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>理想情况全靠 proactive：在还没撞墙时，水位一到阈值就主动压缩，用户无感。</strong> 但现实中估算<a href="/Front2Full/manual/agent/llm-to-agent/token-budget">总有误差</a>，偶尔会“没料到就超了”——这时 reactive 兜底：捕获 <code>prompt too long</code> 错误，压缩历史，然后<strong>重试</strong>刚才那个失败的请求。这也呼应了<a href="/Front2Full/manual/agent/llm-to-agent/error-recovery">第六阶段</a>错误恢复的思路——把“上下文超长”当成一种<strong>可恢复</strong>的错误，而不是终点。两条路一主一备，才稳。</p></div><p>还有一个不能忘的细节：<strong>压缩本身也要消耗上下文</strong>(要把老历史发给模型)。所以<a href="/Front2Full/manual/agent/llm-to-agent/token-budget">水位线那篇</a>强调的“提前动手、留出余量”在这里兑现——你不能等 100% 满了才压，那时连“执行压缩”的空间都没了。</p><h2 id="五、绕不开的矛盾-压缩-vs-缓存" tabindex="-1">五、绕不开的矛盾：压缩 vs 缓存 <a class="header-anchor" href="#五、绕不开的矛盾-压缩-vs-缓存" aria-label="Permalink to &quot;五、绕不开的矛盾：压缩 vs 缓存&quot;">​</a></h2><p>压缩和<a href="/Front2Full/manual/agent/llm-to-agent/prompt-caching">缓存</a>天然打架，这个矛盾必须正视：</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>压缩重写历史，必然改变字节，于是<a href="/Front2Full/manual/agent/llm-to-agent/prompt-caching">击穿缓存</a>。</strong> 你刚压缩完那一轮，前面辛苦建立的缓存从压缩点起全废，得重新建立。所以压缩不是“纯赚”——它拿“一次缓存重建的代价 + 一次摘要调用的代价”，去换“上下文不爆 + 后续每轮更短”。这笔账通常划算(否则会话根本没法继续)，但你要清楚自己在交易什么。精细的实现会尽量让压缩<strong>只折叠很老、本来也快过期的缓存段</strong>，保住近期的热缓存——这正是<a href="/Front2Full/manual/agent/llm-to-agent/context-compaction">下一篇</a>那些“外科手术式”精细化手段要解决的。</p></div><h2 id="六、小结" tabindex="-1">六、小结 <a class="header-anchor" href="#六、小结" aria-label="Permalink to &quot;六、小结&quot;">​</a></h2><p>自动压缩是上下文工程里“减负”的主力手段，也是有损、有风险、有代价的一步：</p><ol><li><strong>保留近期、摘要远古</strong>，用一条压缩边界切开。</li><li><strong>摘要 prompt 决定成败</strong>——用固定结构强制保留“继续干活所必需”的信息，对抗“压缩即失忆”。</li><li><strong>proactive 主动 + reactive 兜底</strong>，并给压缩本身留出余量。</li><li>正视<strong>压缩击穿缓存</strong>的代价，想清楚这笔交易。</li></ol><p>压缩是“大刀阔斧”——一下折叠掉几十条消息。但有时你想要更精细的控制：比如“只把那几个占了两万 token 的巨型工具结果删掉，别的都留着”。这种“外科手术式”的上下文管理，是<a href="/Front2Full/manual/agent/llm-to-agent/context-compaction">下一篇</a>的主题。</p><hr><p><strong>本篇对应代码</strong>：配套仓库加入 <code>src/compact.ts</code>(阈值触发的摘要压缩)，接入循环的每轮开头。<code>git checkout article-13</code>。</p>`,32)])])}const d=a(e,[["render",l]]);export{c as __pageData,d as default};
